data_contract.table:
id; company_id FK companies (restrict); user_id FK users (restrict); period char(7) "YYYY-MM";
tax_code varchar(16) (copia dal file); salary_cost, contribution_cost, insurance_cost, total_cost decimal(12,2);
ordinary_hours decimal(7,2); hired_on date null; terminated_on date null; imported_by FK users (null on delete);
timestamps. Unique (company_id, user_id, period); index (period, user_id).

endpoint.response:
data: {
  applied: boolean,             (false se dry_run o se ci sono errori)
  period: string|null,          ("YYYY-MM"; null se le righe non hanno un mese unico)
  summary: {
    rows: number, people: number, companies: number,
    total_cost: number,         (somma dei totali delle righe valide, 2 decimali)
    replaced_rows: number       (righe gia' presenti per quel mese, sostituite all'applicazione)
  },
  errors: [{ row: number, column: string|null, message: string }]   (row = numero di riga nel file, intestazione = 1)
}
